"use client"

import * as React from "react"

import {
  useControllableState,
  useDragGesture,
  useLatestRef,
} from "../hooks"
import {
  applyPointerTravel,
  commitDialValue,
  followAngle,
  formatByStep,
  isTickFilled,
  lastDialValue,
  nearestTickIndex,
  pointerTravel,
  progressSweepDegrees,
  ratioAlongRange,
  tickRay,
  turnPixelsFromFace,
  valueDeltaFromTravel,
  valueToAngle,
  DIAL_TICK_INNER_RADIUS,
  type DialDragAxis,
} from "../lib/df-dial"
import {
  resumeUiScrubAudio,
  startUiScrub,
  stopUiScrub,
  updateUiScrub,
} from "../lib/df-scrub-sound"
import { playUiTick, resumeUiTickAudio } from "../lib/df-tick-sound"
import { cn } from "../lib/utils"

const DEFAULT_TICK_COUNT = 36

type DialSize = "sm" | "md" | "lg"

type DialThumb = "dot" | "tick"

type DialLabelPosition = "inside" | "top" | "bottom" | "left" | "right"

type DialValueFormat = "number" | "percent"

type DialRadius =
  | "none"
  | "xxs"
  | "xs"
  | "sm"
  | "md"
  | "lg"
  | "xl"
  | "2xl"
  | "3xl"
  | "4xl"
  | "full"

type DialTickRenderContext = {
  index: number
  count: number
  active: boolean
  filled: boolean
  angle: number
  value: number
}

const DIAL_RADIUS_VAR: Record<DialRadius, string> = {
  none: "0px",
  xxs: "var(--radius-xxs)",
  xs: "var(--radius-xs)",
  sm: "var(--radius-sm)",
  md: "var(--radius-md)",
  lg: "var(--radius-lg)",
  xl: "var(--radius-xl)",
  "2xl": "var(--radius-2xl)",
  "3xl": "var(--radius-3xl)",
  "4xl": "var(--radius-4xl)",
  full: "var(--radius-full)",
}

type DialProps = Omit<
  React.ComponentProps<"div">,
  "defaultValue" | "onChange" | "color"
> & {
  min?: number
  max?: number
  step?: number
  value?: number
  defaultValue?: number
  onValueChange?: (value: number) => void
  wrap?: boolean
  invert?: boolean
  dragAxis?: DialDragAxis
  startAngle?: number
  sweep?: number
  size?: DialSize
  thumb?: DialThumb
  label?: React.ReactNode
  labelPosition?: DialLabelPosition
  labelGap?: string
  showValue?: boolean
  valueFormat?: DialValueFormat
  formatValue?: (value: number) => string
  tickCount?: number
  showTicks?: boolean
  tickFill?: boolean
  tickRadius?: DialRadius
  thumbRadius?: DialRadius
  renderTick?: (tick: DialTickRenderContext) => React.ReactNode
  tickSound?: boolean
  scrubSound?: boolean
  accent?: string
  tickMuted?: string
  tickFilled?: string
  tickActive?: string
  labelColor?: string
  valueColor?: string
  faceBackground?: string
  faceBorder?: string
  progress?: boolean
  progressColor?: string
  tickWidth?: string
  tickLength?: string
  thumbSize?: string
  disabled?: boolean
}

function formatDialValue(
  value: number,
  min: number,
  max: number,
  step: number,
  valueFormat: DialValueFormat,
  formatValue?: (value: number) => string,
  wrap = false
) {
  if (formatValue) return formatValue(value)
  if (valueFormat === "percent") {
    return `${Math.round(ratioAlongRange(value, min, max, wrap) * 100)}%`
  }
  return formatByStep(value, step)
}

function Dial({
  className,
  style,
  min = 0,
  max = 100,
  step = 1,
  value,
  defaultValue,
  onValueChange,
  wrap = false,
  invert = false,
  dragAxis = "all",
  startAngle = 0,
  sweep = 360,
  size = "md",
  thumb = "dot",
  label,
  labelPosition = "inside",
  labelGap,
  showValue = false,
  valueFormat = "number",
  formatValue,
  tickCount = DEFAULT_TICK_COUNT,
  showTicks = true,
  tickFill,
  tickRadius = "none",
  thumbRadius = "full",
  renderTick,
  tickSound = true,
  scrubSound = false,
  accent,
  tickMuted,
  tickFilled,
  tickActive,
  labelColor,
  valueColor,
  faceBackground,
  faceBorder,
  progress = false,
  progressColor,
  tickWidth,
  tickLength,
  thumbSize,
  disabled,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  ref,
  ...props
}: DialProps) {
  const labelId = React.useId()
  const safeStep = step > 0 ? step : 1
  const safeSweep = sweep > 0 ? sweep : 360
  const span = max - min || 1
  const largeStep = Math.max(safeStep, span / 10)

  const [rawValue, setValue] = useControllableState({
    value,
    defaultValue: defaultValue ?? min,
    onChange: onValueChange,
  })

  const current = commitDialValue(rawValue, min, max, safeStep, wrap)
  const currentRef = useLatestRef(current)
  const dragValueRef = React.useRef(current)
  const lastPointerRef = React.useRef<{ x: number; y: number } | null>(null)
  const turnPixelsRef = React.useRef(1)
  const displayAngleRef = React.useRef<number | null>(null)
  const { begin: beginDrag } = useDragGesture()
  const [dragging, setDragging] = React.useState(false)
  const [dragLive, setDragLive] = React.useState<number | null>(null)

  React.useEffect(() => {
    return () => {
      stopUiScrub()
    }
  }, [])

  const visualValue = dragLive ?? current
  const targetAngle = valueToAngle(
    visualValue,
    min,
    max,
    startAngle,
    safeSweep
  )
  const displayAngle =
    dragging || displayAngleRef.current == null
      ? targetAngle
      : followAngle(displayAngleRef.current, targetAngle)
  displayAngleRef.current = displayAngle

  const shownValue = commitDialValue(visualValue, min, max, safeStep, wrap)
  const displayText = formatDialValue(
    shownValue,
    min,
    max,
    safeStep,
    valueFormat,
    formatValue,
    wrap
  )
  const resolvedTickCount = Math.max(2, Math.floor(tickCount))
  const fillTicks = tickFill ?? !(wrap || min < 0)
  const travelSign = invert ? -1 : 1
  const hasLabel = label != null
  const showOutsideLabel =
    hasLabel && labelPosition !== "inside"
  const showInsideLabel = hasLabel && labelPosition === "inside"
  const showCenter = showInsideLabel || showValue
  const resolvedAriaLabelledBy =
    ariaLabelledBy ??
    (hasLabel && ariaLabel == null ? labelId : undefined)
  const activeTick = nearestTickIndex(displayAngle, resolvedTickCount)
  const scrubRatio = ratioAlongRange(visualValue, min, max, wrap)
  const progressAngle = progress
    ? progressSweepDegrees(
        visualValue,
        min,
        max,
        startAngle,
        safeSweep
      )
    : 0
  const hasFaceFill = faceBackground != null && faceBackground !== ""

  const commitValue = React.useCallback(
    (next: number) => {
      if (!Number.isFinite(next)) return
      const snapped = commitDialValue(next, min, max, safeStep, wrap)
      if (tickSound && snapped !== currentRef.current) {
        playUiTick()
      }
      setValue(snapped)
    },
    [currentRef, max, min, safeStep, setValue, tickSound, wrap]
  )

  const applyPointer = React.useCallback(
    (clientX: number, clientY: number) => {
      if (!Number.isFinite(clientX) || !Number.isFinite(clientY)) return
      const last = lastPointerRef.current
      if (last == null) {
        lastPointerRef.current = { x: clientX, y: clientY }
        return
      }
      const travel = pointerTravel(
        clientX - last.x,
        clientY - last.y,
        dragAxis
      )
      lastPointerRef.current = { x: clientX, y: clientY }
      if (travel === 0) return
      const next = applyPointerTravel(
        dragValueRef.current,
        valueDeltaFromTravel(
          travel * travelSign,
          min,
          max,
          turnPixelsRef.current
        ),
        min,
        max,
        wrap
      )
      dragValueRef.current = next
      setDragLive(next)
      commitValue(next)
      if (scrubSound) {
        updateUiScrub(ratioAlongRange(next, min, max, wrap))
      }
    },
    [commitValue, dragAxis, max, min, scrubSound, travelSign, wrap]
  )

  const onFacePointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
    if (disabled) return
    event.preventDefault()
    const face = event.currentTarget
    const rect = face.getBoundingClientRect()
    turnPixelsRef.current = turnPixelsFromFace(
      Math.min(rect.width, rect.height)
    )
    dragValueRef.current = currentRef.current
    lastPointerRef.current = { x: event.clientX, y: event.clientY }
    setDragLive(currentRef.current)
    setDragging(true)
    if (tickSound) resumeUiTickAudio()
    if (scrubSound) {
      resumeUiScrubAudio()
      startUiScrub(scrubRatio)
    }
    beginDrag(event, null, {
      onMove: (moveEvent) => {
        applyPointer(moveEvent.clientX, moveEvent.clientY)
      },
      onEnd: () => {
        stopUiScrub()
        lastPointerRef.current = null
        setDragLive(null)
        setDragging(false)
      },
    })
  }

  const onFaceKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (disabled) return
    if (tickSound) resumeUiTickAudio()
    if (event.key === "ArrowRight" || event.key === "ArrowUp") {
      event.preventDefault()
      commitValue(current + travelSign * safeStep)
    } else if (event.key === "ArrowLeft" || event.key === "ArrowDown") {
      event.preventDefault()
      commitValue(current - travelSign * safeStep)
    } else if (event.key === "Home") {
      event.preventDefault()
      commitValue(min)
    } else if (event.key === "End") {
      event.preventDefault()
      commitValue(lastDialValue(min, max, safeStep, wrap))
    } else if (event.key === "PageUp") {
      event.preventDefault()
      commitValue(current + travelSign * largeStep)
    } else if (event.key === "PageDown") {
      event.preventDefault()
      commitValue(current - travelSign * largeStep)
    }
  }

  const purposeLabel = hasLabel ? (
    <span data-df="dial-label" id={labelId}>
      {label}
    </span>
  ) : null

  const ticks = showTicks
    ? Array.from({ length: resolvedTickCount }, (_, index) => {
        const angle = (index / resolvedTickCount) * 360
        const filled =
          fillTicks && isTickFilled(angle, startAngle, safeSweep, scrubRatio)
        const active = thumb === "tick" && index === activeTick
        const custom = renderTick?.({
          index,
          count: resolvedTickCount,
          active,
          filled,
          angle,
          value: shownValue,
        })
        const tickStyle = {
          "--df-dial-tick-angle": `${angle}deg`,
        } as React.CSSProperties
        if (custom != null) {
          return {
            kind: "custom" as const,
            node: (
              <span
                key={index}
                data-df="dial-tick-host"
                data-filled={filled ? "" : undefined}
                data-active={active ? "" : undefined}
                style={tickStyle}
              >
                {custom}
              </span>
            ),
          }
        }
        const ray = tickRay(angle, 50, 50, 50, DIAL_TICK_INNER_RADIUS)
        return {
          kind: "mark" as const,
          node: (
            <line
              key={index}
              data-df="dial-tick"
              data-filled={filled ? "" : undefined}
              data-active={active ? "" : undefined}
              x1={ray.x1}
              y1={ray.y1}
              x2={ray.x2}
              y2={ray.y2}
            />
          ),
        }
      })
    : []
  const tickMarks = ticks
    .filter((tick) => tick.kind === "mark")
    .map((tick) => tick.node)
  const tickHosts = ticks
    .filter((tick) => tick.kind === "custom")
    .map((tick) => tick.node)

  const rootStyle = {
    "--df-dial-angle": `${displayAngle}deg`,
    "--df-dial-tick-radius": DIAL_RADIUS_VAR[tickRadius],
    "--df-dial-tick-cap": tickRadius === "full" ? "round" : "butt",
    "--df-dial-thumb-radius": DIAL_RADIUS_VAR[thumbRadius],
    ...(accent ? { "--df-dial-accent": accent } : null),
    ...(tickMuted ? { "--df-dial-tick-muted": tickMuted } : null),
    ...(tickFilled ? { "--df-dial-tick-filled": tickFilled } : null),
    ...(tickActive ? { "--df-dial-tick-active": tickActive } : null),
    ...(labelColor ? { "--df-dial-label-color": labelColor } : null),
    ...(valueColor ? { "--df-dial-value-color": valueColor } : null),
    ...(faceBackground ? { "--df-dial-face-bg": faceBackground } : null),
    ...(faceBorder ? { "--df-dial-face-border": faceBorder } : null),
    ...(progress
      ? {
          "--df-dial-progress-from": `${startAngle}deg`,
          "--df-dial-progress-angle": `${progressAngle}deg`,
        }
      : null),
    ...(progressColor ? { "--df-dial-progress-color": progressColor } : null),
    ...(tickWidth ? { "--df-dial-tick-width": tickWidth } : null),
    ...(tickLength ? { "--df-dial-tick-length": tickLength } : null),
    ...(thumbSize ? { "--df-dial-thumb-size": thumbSize } : null),
    ...(labelGap ? { "--df-dial-label-gap": labelGap } : null),
    ...style,
  } as React.CSSProperties

  return (
    <div
      ref={ref}
      data-df="dial"
      data-size={size}
      data-thumb={thumb}
      data-drag-axis={dragAxis}
      data-wrap={wrap ? "" : undefined}
      data-invert={invert ? "" : undefined}
      data-face={hasFaceFill ? "fill" : undefined}
      data-progress={progress ? "" : undefined}
      data-label-position={hasLabel ? labelPosition : undefined}
      data-dragging={dragging ? "" : undefined}
      data-disabled={disabled ? "" : undefined}
      className={cn(className)}
      style={rootStyle}
      {...props}
    >
      {labelPosition === "top" && showOutsideLabel ? purposeLabel : null}
      {labelPosition === "left" && showOutsideLabel ? purposeLabel : null}
      <div
        data-df="dial-face"
        role="slider"
        tabIndex={disabled ? -1 : 0}
        aria-label={ariaLabel}
        aria-labelledby={resolvedAriaLabelledBy}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={current}
        aria-valuetext={displayText}
        aria-disabled={disabled || undefined}
        onPointerDown={onFacePointerDown}
        onKeyDown={onFaceKeyDown}
      >
        {progress ? (
          <span data-df="dial-progress" aria-hidden="true" />
        ) : null}
        {(showTicks || thumb === "dot") ? (
          <div data-df="dial-ticks" aria-hidden="true">
            {showTicks && tickMarks.length > 0 ? (
              <svg viewBox="0 0 100 100" focusable="false">
                {tickMarks}
              </svg>
            ) : null}
            {showTicks ? tickHosts : null}
            {thumb === "dot" ? (
              <span data-df="dial-thumb-orbit">
                <span data-df="dial-thumb" />
              </span>
            ) : null}
          </div>
        ) : null}
        {showCenter ? (
          <span
            data-df="dial-center"
            data-with-value={
              showInsideLabel && showValue ? "" : undefined
            }
          >
            {showInsideLabel ? purposeLabel : null}
            {showValue ? (
              <span data-df="dial-value">{displayText}</span>
            ) : null}
          </span>
        ) : null}
      </div>
      {labelPosition === "right" && showOutsideLabel ? purposeLabel : null}
      {labelPosition === "bottom" && showOutsideLabel ? purposeLabel : null}
    </div>
  )
}

export { Dial }
export type {
  DialDragAxis,
  DialLabelPosition,
  DialProps,
  DialRadius,
  DialSize,
  DialThumb,
  DialTickRenderContext,
  DialValueFormat,
}

export type DialDragAxis = "all" | "horizontal" | "vertical"

export function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value))
}

function quantizeToStep(value: number, min: number, step: number) {
  const safeStep = step > 0 ? step : 1
  const stepped = Math.round((value - min) / safeStep) * safeStep + min
  const precision = String(safeStep).includes(".")
    ? (String(safeStep).split(".")[1]?.length ?? 0)
    : 0
  return precision > 0 ? Number(stepped.toFixed(precision)) : stepped
}

export function snapToStep(
  value: number,
  min: number,
  max: number,
  step: number
) {
  return clamp(quantizeToStep(value, min, step), min, max)
}

/** Wrap a ring heading into 0 to 360. */
export function wrapDegrees(degrees: number) {
  return ((degrees % 360) + 360) % 360
}

/** Signed shortest turn from one ring heading to another. */
export function shortestAngleDelta(from: number, to: number) {
  const delta = wrapDegrees(to - from)
  return delta > 180 ? delta - 360 : delta
}

/** Wrap a value into [min, max). */
export function wrapValue(value: number, min: number, max: number) {
  const span = max - min
  if (!(span > 0)) return min
  let t = (value - min) % span
  if (t < 0) t += span
  const next = min + t
  return next >= max ? min : next
}

export function commitDialValue(
  raw: number,
  min: number,
  max: number,
  step: number,
  wrap: boolean
) {
  if (!Number.isFinite(raw)) return min
  if (wrap) return wrapValue(quantizeToStep(raw, min, step), min, max)
  return snapToStep(raw, min, max, step)
}

/** Last resting value in the range. Wrap excludes max. */
export function lastDialValue(
  min: number,
  max: number,
  step: number,
  wrap: boolean
) {
  if (!wrap) return snapToStep(max, min, max, step)
  const span = max - min
  if (!(span > 0)) return min
  const safeStep = step > 0 ? step : 1
  let steps = Math.floor(span / safeStep)
  if (min + steps * safeStep >= max) steps -= 1
  if (steps < 0) return min
  return wrapValue(
    quantizeToStep(min + steps * safeStep, min, safeStep),
    min,
    max
  )
}

/** Position of a value across min to max, from 0 to 1. */
export function ratioAlongRange(
  value: number,
  min: number,
  max: number,
  wrap = false
) {
  const span = max - min
  if (!(span > 0) || !Number.isFinite(value)) return 0
  const source = wrap ? wrapValue(value, min, max) : value
  return clamp((source - min) / span, 0, 1)
}

/**
 * Pointer travel in pixels along the configured drag axis.
 * all: right and up increase, left and down decrease, diagonals combine.
 * horizontal: only left and right. vertical: up increases, down decreases.
 */
export function pointerTravel(
  dx: number,
  dy: number,
  axis: DialDragAxis
) {
  if (!Number.isFinite(dx) || !Number.isFinite(dy)) return 0
  if (axis === "horizontal") return dx
  if (axis === "vertical") return -dy
  return (dx - dy) / Math.SQRT2
}

/** Pixel travel that maps to one full min to max loop. */
export function turnPixelsFromFace(size: number) {
  if (!(size > 0)) return 1
  return Math.PI * size
}

/** Next drag value from a value delta. Wrap keeps an open accumulator. */
export function applyPointerTravel(
  current: number,
  delta: number,
  min: number,
  max: number,
  wrap: boolean
) {
  const next = current + delta
  if (!Number.isFinite(next)) {
    return Number.isFinite(current) ? current : min
  }
  if (wrap) return next
  return clamp(next, min, max)
}

export function valueDeltaFromTravel(
  travel: number,
  min: number,
  max: number,
  turnPixels: number
) {
  const span = max - min
  if (!(turnPixels > 0) || !(span > 0) || !Number.isFinite(travel)) return 0
  return (travel / turnPixels) * span
}

/** Keep ring rotation continuous across wrap. */
export function followAngle(previous: number, target: number) {
  if (!Number.isFinite(previous)) return target
  if (!Number.isFinite(target)) return previous
  return previous + shortestAngleDelta(wrapDegrees(previous), wrapDegrees(target))
}

/**
 * Map a value onto the ring. Headings are clockwise from the top.
 * When min is 0 or greater, min sits at startAngle and max at startAngle plus sweep.
 * When min is below 0 and max is above 0, value 0 sits at startAngle.
 */
export function valueToAngle(
  value: number,
  min: number,
  max: number,
  startAngle: number,
  sweep: number
) {
  const safeSweep = sweep > 0 ? sweep : 360
  if (!Number.isFinite(value)) return startAngle
  if (min < 0 && max > 0) {
    const unit = Math.max(Math.abs(min), max)
    if (!(unit > 0)) return startAngle
    return startAngle + (value / unit) * safeSweep
  }
  const span = max - min || 1
  return startAngle + ((value - min) / span) * safeSweep
}

/** Clockwise arc from startAngle to the current value, in 0 to sweep. */
export function progressSweepDegrees(
  value: number,
  min: number,
  max: number,
  startAngle: number,
  sweep: number
) {
  const safeSweep = sweep > 0 ? sweep : 360
  const raw =
    valueToAngle(value, min, max, startAngle, safeSweep) - startAngle
  if (!Number.isFinite(raw) || raw === 0) return 0
  const wrapped = wrapDegrees(raw)
  if (wrapped === 0) return safeSweep
  return wrapped
}

/** Inner end of each SVG tick, in viewBox units. The CSS tick mask owns the visible length, so this must sit inside that band. */
export const DIAL_TICK_INNER_RADIUS = 20

/**
 * Line from the ring edge inward. angle 0 is the top, then clockwise.
 * viewBox is 0 0 100 100. Omit innerRadius to run to the center.
 */
export function tickRay(
  angleDeg: number,
  cx = 50,
  cy = 50,
  radius = 50,
  innerRadius?: number
) {
  if (!Number.isFinite(angleDeg) || !(radius > 0)) {
    return { x1: cx, y1: cy - radius, x2: cx, y2: cy }
  }
  const rad = (angleDeg * Math.PI) / 180
  const x1 = cx + radius * Math.sin(rad)
  const y1 = cy - radius * Math.cos(rad)
  const inner =
    innerRadius == null
      ? 0
      : Number.isFinite(innerRadius)
        ? Math.min(radius, Math.max(0, innerRadius))
        : 0
  return {
    x1,
    y1,
    x2: cx + inner * Math.sin(rad),
    y2: cy - inner * Math.cos(rad),
  }
}

export function nearestTickIndex(
  angle: number,
  tickCount: number,
  tickOrigin = 0
) {
  const count = Math.max(2, Math.floor(tickCount))
  const step = 360 / count
  let best = 0
  let bestDist = Number.POSITIVE_INFINITY
  for (let index = 0; index < count; index++) {
    const tickAngle = tickOrigin + index * step
    const dist = Math.abs(shortestAngleDelta(angle, wrapDegrees(tickAngle)))
    if (dist < bestDist) {
      best = index
      bestDist = dist
    }
  }
  return best
}

/** True when a tick heading sits on the filled arc from min to the current ratio. */
export function isTickFilled(
  tickAngle: number,
  startAngle: number,
  sweep: number,
  ratio: number
) {
  const fillEps = 1e-6
  const safeSweep = sweep > 0 ? sweep : 360
  const fromStart = wrapDegrees(tickAngle - startAngle)
  const safeRatio = clamp(ratio, 0, 1)
  if (safeSweep < 360 && fromStart > safeSweep + fillEps) return false
  if (safeRatio >= 1) return true
  return fromStart <= safeSweep * safeRatio + fillEps
}

export function formatByStep(value: number, step: number) {
  const safeStep = step > 0 ? step : 1
  const digits = safeStep >= 1 ? 0 : safeStep >= 0.1 ? 1 : 2
  return value.toFixed(digits)
}

type AudioContextConstructor = typeof AudioContext

let sharedContext: AudioContext | null = null

function getAudioContextConstructor(): AudioContextConstructor | null {
  if (typeof window === "undefined") return null
  const fromWindow = window.AudioContext
  if (fromWindow) return fromWindow
  const legacy = (
    window as Window & { webkitAudioContext?: AudioContextConstructor }
  ).webkitAudioContext
  return legacy ?? null
}

export function getUiAudioContext(): AudioContext | null {
  const Constructor = getAudioContextConstructor()
  if (!Constructor) return null
  if (!sharedContext || sharedContext.state === "closed") {
    sharedContext = new Constructor()
  }
  return sharedContext
}

export function resumeUiAudio(): void {
  const ctx = getUiAudioContext()
  if (!ctx || ctx.state !== "suspended") return
  void ctx.resume()
}

export function uiAudioAllowed(): boolean {
  if (typeof document !== "undefined" && document.hidden) return false
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") {
    return true
  }
  return !window.matchMedia("(prefers-reduced-motion: reduce)").matches
}

import {
  getUiAudioContext,
  resumeUiAudio,
  uiAudioAllowed,
} from "../df-ui-audio"

type TickSoundOptions = {
  volume?: number
}

export function resumeUiTickAudio(): void {
  resumeUiAudio()
}

export function playUiTick(options?: TickSoundOptions): void {
  if (!uiAudioAllowed()) return

  const ctx = getUiAudioContext()
  if (!ctx) return
  if (ctx.state === "suspended") {
    void ctx.resume()
  }

  const volume = Math.min(1, Math.max(0, options?.volume ?? 0.14))
  const t0 = ctx.currentTime
  const duration = 0.03
  const sampleCount = Math.max(1, Math.floor(ctx.sampleRate * duration))
  const buffer = ctx.createBuffer(1, sampleCount, ctx.sampleRate)
  const data = buffer.getChannelData(0)
  for (let i = 0; i < sampleCount; i++) {
    const env = 1 - i / sampleCount
    data[i] = (Math.random() * 2 - 1) * env * env
  }

  const noise = ctx.createBufferSource()
  noise.buffer = buffer

  const bandpass = ctx.createBiquadFilter()
  bandpass.type = "bandpass"
  bandpass.frequency.value = 2450
  bandpass.Q.value = 1.35

  const noiseGain = ctx.createGain()
  noiseGain.gain.setValueAtTime(volume * 0.5, t0)
  noiseGain.gain.exponentialRampToValueAtTime(0.0001, t0 + duration)

  noise.connect(bandpass)
  bandpass.connect(noiseGain)
  noiseGain.connect(ctx.destination)

  const osc = ctx.createOscillator()
  osc.type = "triangle"
  osc.frequency.setValueAtTime(1720, t0)
  osc.frequency.exponentialRampToValueAtTime(680, t0 + 0.034)

  const oscGain = ctx.createGain()
  oscGain.gain.setValueAtTime(volume * 0.32, t0)
  oscGain.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.038)

  osc.connect(oscGain)
  oscGain.connect(ctx.destination)

  noise.start(t0)
  osc.start(t0)
  osc.stop(t0 + 0.045)
}

import {
  getUiAudioContext,
  resumeUiAudio,
  uiAudioAllowed,
} from "../df-ui-audio"

const SCRUB_FREQ_MIN = 210
const SCRUB_FREQ_SPAN = 260
const SCRUB_FILTER_IDLE = 720
const SCRUB_FILTER_SPAN = 980
const SCRUB_GAIN_IDLE = 0.018
const SCRUB_GAIN_MOVE = 0.055
const SCRUB_GAIN_SILENCE = 0.0001
const SCRUB_SPEED_REF = 1.8
const SCRUB_FREQ_SMOOTH = 0.045
const SCRUB_FILTER_SMOOTH = 0.05
const SCRUB_GAIN_SMOOTH = 0.04
const SCRUB_STOP_FADE = 0.03
const SCRUB_STOP_DISPOSE_MS = 140

type ScrubDisposableGraph = {
  osc: { stop: () => void; disconnect: () => void }
  filter: { disconnect: () => void }
  gain: { disconnect: () => void }
  stopped: boolean
}

type ScrubSession = ScrubDisposableGraph & {
  osc: OscillatorNode
  filter: BiquadFilterNode
  gain: GainNode
  lastRatio: number
  lastTime: number
}

type ScrubDisposeResult = "stopped" | "already-stopped" | "failed"

let session: ScrubSession | null = null
let stopTimer: ReturnType<typeof setTimeout> | null = null
let watchingVisibility = false
let scrubSoundDisabled = false
let scrubSoundFailure: unknown | null = null

function isAlreadyStoppedOscillatorError(cause: unknown): boolean {
  return cause instanceof DOMException && cause.name === "InvalidStateError"
}

function recordScrubSoundFailure(cause: unknown) {
  scrubSoundFailure = cause
  scrubSoundDisabled = true
}

/** Last unexpected dispose failure, or null when scrub audio has not failed. */
export function getUiScrubSoundFailure(): unknown | null {
  return scrubSoundFailure
}

/**
 * False after an unexpected dispose failure, or when the environment blocks UI audio.
 * Once disabled by a failure, scrub stays off until `clearUiScrubSoundFailure`.
 */
export function isUiScrubSoundAvailable(): boolean {
  if (scrubSoundDisabled) return false
  return uiAudioAllowed() && getUiAudioContext() != null
}

/** Clears a recorded dispose failure so scrub audio can be attempted again. */
export function clearUiScrubSoundFailure(): void {
  scrubSoundFailure = null
  scrubSoundDisabled = false
}

function clamp01(value: number) {
  return Math.min(1, Math.max(0, value))
}

function freqForRatio(ratio: number) {
  return SCRUB_FREQ_MIN + clamp01(ratio) * SCRUB_FREQ_SPAN
}

function clearStopTimer() {
  if (stopTimer == null) return
  clearTimeout(stopTimer)
  stopTimer = null
}

function handleVisibilityChange() {
  if (typeof document !== "undefined" && document.hidden) {
    stopUiScrub()
  }
}

function setVisibilityWatch(enabled: boolean) {
  if (typeof document === "undefined") return
  if (enabled && !watchingVisibility) {
    document.addEventListener("visibilitychange", handleVisibilityChange)
    watchingVisibility = true
    return
  }
  if (!enabled && watchingVisibility) {
    document.removeEventListener("visibilitychange", handleVisibilityChange)
    watchingVisibility = false
  }
}

function disconnectSession(next: ScrubDisposableGraph) {
  next.osc.disconnect()
  next.filter.disconnect()
  next.gain.disconnect()
}

/**
 * Stops and disconnects a scrub graph. Never throws.
 * Unexpected errors are recorded via `getUiScrubSoundFailure` and disable scrub audio.
 */
function disposeSession(next: ScrubDisposableGraph): ScrubDisposeResult {
  let result: ScrubDisposeResult = "stopped"
  try {
    if (next.stopped) {
      result = "already-stopped"
    } else {
      next.stopped = true
      try {
        next.osc.stop()
      } catch (cause) {
        if (isAlreadyStoppedOscillatorError(cause)) {
          result = "already-stopped"
        } else {
          recordScrubSoundFailure(cause)
          result = "failed"
        }
      }
    }
  } finally {
    try {
      disconnectSession(next)
    } catch (cause) {
      recordScrubSoundFailure(cause)
      result = "failed"
    }
  }
  return result
}

/** Clears module session state first, then disposes. Never throws. */
function discardUiScrubSession(): ScrubDisposeResult | null {
  if (session == null) return null
  const active = session
  session = null
  return disposeSession(active)
}

export function resumeUiScrubAudio(): void {
  resumeUiAudio()
}

export function startUiScrub(ratio: number): void {
  clearStopTimer()
  const outcome = discardUiScrubSession()
  if (outcome === "failed") {
    setVisibilityWatch(false)
    return
  }
  if (scrubSoundDisabled || !uiAudioAllowed()) {
    setVisibilityWatch(false)
    return
  }

  const ctx = getUiAudioContext()
  if (!ctx) return
  if (ctx.state === "suspended") {
    void ctx.resume()
  }

  const osc = ctx.createOscillator()
  osc.type = "sine"
  osc.frequency.value = freqForRatio(ratio)

  const filter = ctx.createBiquadFilter()
  filter.type = "lowpass"
  filter.frequency.value = SCRUB_FILTER_IDLE
  filter.Q.value = 0.7

  const gain = ctx.createGain()
  gain.gain.value = SCRUB_GAIN_IDLE

  osc.connect(filter)
  filter.connect(gain)
  gain.connect(ctx.destination)
  osc.start()

  session = {
    osc,
    filter,
    gain,
    lastRatio: clamp01(ratio),
    lastTime: performance.now(),
    stopped: false,
  }
  setVisibilityWatch(true)
}

export function updateUiScrub(ratio: number, now = performance.now()): void {
  if (!session) return
  if (scrubSoundDisabled || !uiAudioAllowed()) {
    stopUiScrub()
    return
  }

  const nextRatio = clamp01(ratio)
  const dt = Math.max(0.001, (now - session.lastTime) / 1000)
  const speed = clamp01(
    Math.abs(nextRatio - session.lastRatio) / dt / SCRUB_SPEED_REF
  )
  const t = session.osc.context.currentTime

  session.osc.frequency.setTargetAtTime(
    freqForRatio(nextRatio),
    t,
    SCRUB_FREQ_SMOOTH
  )
  session.filter.frequency.setTargetAtTime(
    SCRUB_FILTER_IDLE + speed * SCRUB_FILTER_SPAN,
    t,
    SCRUB_FILTER_SMOOTH
  )
  session.gain.gain.setTargetAtTime(
    SCRUB_GAIN_IDLE + speed * (SCRUB_GAIN_MOVE - SCRUB_GAIN_IDLE),
    t,
    SCRUB_GAIN_SMOOTH
  )

  session.lastRatio = nextRatio
  session.lastTime = now
}

export function stopUiScrub(): void {
  if (!session) {
    setVisibilityWatch(false)
    return
  }
  const active = session
  session = null
  clearStopTimer()

  try {
    const t = active.osc.context.currentTime
    active.gain.gain.cancelScheduledValues(t)
    active.gain.gain.setTargetAtTime(SCRUB_GAIN_SILENCE, t, SCRUB_STOP_FADE)
  } catch (cause) {
    recordScrubSoundFailure(cause)
    disposeSession(active)
    setVisibilityWatch(false)
    return
  }

  stopTimer = setTimeout(() => {
    stopTimer = null
    disposeSession(active)
    if (!session) setVisibilityWatch(false)
  }, SCRUB_STOP_DISPOSE_MS)
}
